            r += 1
            continue
        start = r
        while r < h and any(x != bg for x in grid[r]):
            r += 1
        blocks.append(list(range(start, r)))

    if len(blocks) < 2:
        return out

    # Find a row with a long solid rightward continuation, then match it to
    # the analogous row in the other block (allowing a one-cell offset).
    candidates = []
    for bi in range(len(blocks)):
        for bj in range(bi + 1, len(blocks)):
            for donor_block, target_block in ((blocks[bi], blocks[bj]),
                                               (blocks[bj], blocks[bi])):
                for dr in donor_block:
                    row = grid[dr]
                    end = max((c for c, v in enumerate(row) if v != bg), default=-1)
                    if end < 0:
                        continue
                    start = end
                    while start > 0 and row[start - 1] != bg:
                        start -= 1
                    if end - start + 1 < 5:
                        continue

                    for tr in target_block:
                        te = max((c for c, v in enumerate(grid[tr]) if v != bg), default=-1)
                        if te < 0 or te >= end:
                            continue

                        # Compare the motif before the donor's solid tail,
                        # allowing a small horizontal displacement.
                        best = None
                        for shift in (-1, 0, 1):
                            matches = total = 0
                            for c in range(start):
                                q = c + shift
                                if 0 <= q < w:
                                    total += 1
                                    matches += (row[c] == grid[tr][q])
                            score = matches / total if total else 0
                            if best is None or score > best[0]:
                                best = (score, shift)
                        if best and best[0] >= 0.65:
                            candidates.append((best[0], end - te, tr, te, end))

    if candidates:
        _, _, row, old_end, new_end = max(candidates)
        for c in range(old_end + 1, new_end + 1):
            if grid[row][c] == bg:
                out[row][c] = 1

